export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/brief')return handleBriefAnalysis(request,env);if(url.pathname==='/api/requests')return handleSubmission(request,env);if(url.pathname.startsWith('/api/zoho/')||['/zoho-connect','/zoho-connected'].includes(url.pathname))return handleZoho(request,env);if(url.pathname.startsWith('/api/'))return new Response('Not found',{status:404});if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const asset=assets[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});const bytes=Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Cache-Control':'no-cache'}})}};
